import numpy as np, sys; sys.path.insert(0,str(WORK))
exec(open(WORK/'lib.py').read())
F = np.load(WORK/'base_feats.npz'); y=F['y']
def LNr(X): X=X-X.mean(1,keepdims=True); return X/X.std(1,keepdims=True)
X = LNr(5*F['mean_hidden_L9']+F['cls_hidden_L9'])[:,KEEP]
def sor_cv(X,y,nunits=768,gamma=0.4,b0=None,lams=(1e-4,1e-3,1e-2,1e-1),seeds=(0,1,2)):
    n=len(y); res={l:0 for l in lams}
    for s in seeds:
        for te in folds(n,5,s,y):
            tr=np.setdiff1d(np.arange(n),te)
            mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; Z=(X-mu)/sd/np.sqrt(X.shape[1])
            rng=np.random.default_rng(s); ci=rng.choice(tr,nunits,replace=False)
            if b0 is None: f=lambda A,B: np.exp(2*gamma*(A@B.T-1))
            else: f=lambda A,B: np.tanh(gamma*A@B.T+b0)+1
            H=f(Z,Z[ci]); Kcc=f(Z[ci],Z[ci]); Kcc=(Kcc+Kcc.T)/2
            T=np.eye(8)[y[tr]]-1/8; Ht=H[tr]; G=Ht.T@Ht; R=Ht.T@T
            for l in lams:
                B=np.linalg.solve(G+l*Kcc+1e-8*np.trace(G)/len(G)*np.eye(len(G)),R); res[l]+=((H[te]@B).argmax(1)==y[te]).sum()
    return {l:round(v/(n*len(seeds)),4) for l,v in res.items()}
for g in (0.2,0.4,0.8):
    print('exp',g,sor_cv(X,y,gamma=g))
